<?php

/* @autogenerated */
declare(strict_types=1);

namespace Tests\integration\Features\OAuth\Stub;

use DateInterval;
use Override;
use Ramsey\Uuid\Uuid;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\MagicLinkSession;
use Civi\Lughauth\Features\OAuth\MagicLink\Domain\Gateway\MagicLinkSessionGateway;

final class InMemoryMagicLinkSessionGateway implements MagicLinkSessionGateway
{
    #[Override]
    public function createSession(
        string $userUid,
        string $email,
        string $tenantUid,
        string $tenantName,
        string $clientId,
    ): ?MagicLinkSession {
        if ($clientId === '') {
            return null;
        }
        return new MagicLinkSession(Uuid::uuid4()->toString(), new DateInterval('P15D'));
    }
}
